def transform(grid):
    rows, cols = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    pieces = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            for mask, color in ((7, 3), (11, 3), (13, 4), (14, 2), (15, 1)):
                cells = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2)
                                  if mask & (1 << (dr * 2 + dc)))
                if cells <= occupied:
                    pieces.append((cells, color))
    by_cell = {cell: [] for cell in occupied}
    for piece in pieces:
        for cell in piece[0]: by_cell[cell].append(piece)
    def solve(remaining):
        if not remaining: return []
        cell = min(remaining, key=lambda x: sum(p[0] <= remaining for p in by_cell[x]))
        for piece in by_cell[cell]:
            if piece[0] <= remaining:
                rest = solve(remaining - piece[0])
                if rest is not None: return [piece] + rest
        return None
    tiling = solve(occupied)
